{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "@id": "https://www.goldeneraremodel.com/faq#faqpage",
  "url": "https://www.goldeneraremodel.com/faq",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "What areas do you serve in the Dallas–Fort Worth metroplex?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "We serve the entire DFW metro from our Mansfield base — including Dallas, Fort Worth, Arlington, Plano, Frisco, McKinney, Southlake, Keller, Irving, Richardson, Garland, Mesquite, and surrounding areas across Collin, Dallas, Denton, Kaufman, Tarrant, and Rockwall counties. If you’re within about 45 minutes of Mansfield, we can come out."
      }
    },
    {
      "@type": "Question",
      "name": "How much does a bathroom remodel cost in DFW?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Most DFW bathroom remodels we do fall between $15,000 and $45,000, depending on the size of the space and the finishes you choose. A straightforward guest bathroom refresh with new tile, vanity, and fixtures is typically $15K–$22K. A full master bath with walk-in shower, custom tile, and stone work usually lands $30K–$45K+. We give you a detailed line-item quote after a free in-home consultation — no surprise fees mid-project."
      }
    },
    {
      "@type": "Question",
      "name": "How long does a bathroom remodel take?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Guest bathroom: typically 2–3 weeks once we start. Master bathroom with walk-in shower and custom tile: 4–6 weeks. Full primary suite with custom millwork or natural stone: 6–8 weeks. We give you a firm schedule up front and we don’t start until we have all the materials on hand."
      }
    },
    {
      "@type": "Question",
      "name": "Do you install walk-in showers and curbless showers?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes — walk-in showers and curbless (zero-threshold) showers are one of our specialties. We handle the waterproofing, linear drain installation, custom tile work, glass selection, and fixture install. Curbless showers require precise sloping of the subfloor, which is why homeowners hire us specifically for them — it’s not a job for a general handyman."
      }
    },
    {
      "@type": "Question",
      "name": "Do you offer free estimates?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. All in-home consultations and estimates are free, with no obligation. Most projects get quoted within 48 hours of the visit. Call or text (469) 586-6478 to schedule — evenings and weekends are fine. We’ll come out, measure, talk through your goals, and send you a detailed line-item quote."
      }
    },
    {
      "@type": "Question",
      "name": "Are you licensed and insured?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes — Golden Era Remodel is fully licensed and insured in Texas. We carry general liability and workers’ comp on every job. We’re happy to provide certificates of insurance on request before the project starts. We’ve been in business since 2020 with 85+ five-star Google reviews."
      }
    },
    {
      "@type": "Question",
      "name": "Do you handle everything or do I need to hire multiple contractors?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "We handle the whole project in-house and with our trusted sub-trades — demolition, framing, plumbing, electrical, tile, cabinetry, counters, glass, paint, and finish carpentry. One point of contact (Anthony), one contract, one schedule. You don’t have to coordinate between a tile guy, a plumber, and an electrician — that’s our job."
      }
    },
    {
      "@type": "Question",
      "name": "Do I pick out my own materials or do you?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Both options work — whatever you prefer. Most clients want help picking, so we walk you through tile showrooms, cabinet options, and counter slabs. We have relationships with DFW suppliers that often get us better pricing than retail. If you already have a Pinterest board full of ideas, even better — we’ll help you turn that into a realistic, on-budget plan."
      }
    },
    {
      "@type": "Question",
      "name": "Will I still be able to use the bathroom during the remodel?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "During demolition and installation the bathroom will be out of service. If it’s your only bathroom, we plan the schedule around you and work to minimize downtime. Most guest bathrooms are offline for 2–3 weeks; master bathrooms for 4–6 weeks. We keep the rest of the home clean with dust barriers and protect floors and walkways every day."
      }
    },
    {
      "@type": "Question",
      "name": "What kind of warranty do you offer?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "We provide a 1-year installation warranty on our workmanship. If something we installed fails due to our craftsmanship, we come back and make it right. Manufacturer warranties on tile, fixtures, cabinets, and appliances come directly from the manufacturer and typically range from 1 year to lifetime depending on the product."
      }
    },
    {
      "@type": "Question",
      "name": "What happens if you find unexpected issues during the remodel (rot, leaks, old wiring)?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "It happens on about 1 in 4 older-home remodels. When we find hidden damage — water rot behind tile, failed waterproofing, undersized wiring, old galvanized plumbing — we stop, photograph it, and get you a written change order before doing any extra work. You see the issue, you see the cost, you approve it. No surprise charges at the end."
      }
    },
    {
      "@type": "Question",
      "name": "What’s your payment schedule? Do you offer financing?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Payment is typically structured as a deposit at contract signing, progress payments at defined milestones (demo complete, rough-in complete, tile done, etc.), and final payment on completion. We accept credit cards, debit cards, checks, and NFC mobile payments. We don’t offer in-house financing, but we can point you to HELOC and home-improvement loan options most clients use."
      }
    },
    {
      "@type": "Question",
      "name": "How do I get started?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Call or text (469) 586-6478, or submit the contact form on our site. We’ll schedule a free in-home consultation — usually within a week. At the visit we’ll measure, walk through your goals, show you options, and get you a detailed written quote within 48 hours. No pressure, no obligation."
      }
    }
  ]
}

